'use strict';
const $=id=>document.getElementById(id), app=$('app'), DAY=86400000, KEY='recall-data-v1';
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=(front,back)=>({id:uid(),front,back,due:0,interval:0,reps:0,lapses:0});
const deck=(name,folder,pairs)=>({id:uid(),name,folder,cards:pairs.map(p=>card(...p))});
const initial=()=>({version:1,theme:'system',folders:['Speech','Debate','French','Science','Math'],decks:[deck('Sophisticated theses','Speech',[['Courage','Courage is the willingness to act despite fear.'],['Duty','Our most meaningful responsibilities are sometimes chosen rather than imposed.'],['Success','Success becomes dangerous when achievement replaces purpose.'],['Failure','Failure becomes valuable when it leads to reflection and adaptation.'],['Freedom','Freedom without responsibility can undermine the freedom of others.'],['Loyalty','Genuine loyalty sometimes requires disagreement rather than unconditional support.']]),deck('Psychology and philosophy','Debate',[['Cognitive dissonance','Mental discomfort caused by conflicting beliefs or behaviours.'],['Confirmation bias','Favouring information that supports existing beliefs.'],['Opportunity cost','The value of the next-best alternative sacrificed by a decision.'],['Groupthink','Prioritizing group agreement over independent critical thinking.'],['Veil of ignorance','Design society without knowing your own position within it.'],['Loss aversion','Losses may feel stronger than equivalent gains.']])],reviews:[]});
let db;try{const raw=localStorage.getItem(KEY);db=raw?JSON.parse(raw):initial()}catch(e){db=initial();setTimeout(()=>notify('Saved data could not be read. Export any recoverable backup before continuing.'),0)}
let page='home',folder='',activeDeck=null,session=null,preview=[],noticeTimer,storageOK=true;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));storageOK=true;return true}catch(e){storageOK=false;notify('Storage failed. Export a backup now; changes may not survive closing the app.');return false}}
function notify(s){$('notice').textContent=s;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').textContent='',4500)}
function theme(){document.documentElement.dataset.theme=db.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):db.theme}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',theme);theme();save();
const all=()=>db.decks.flatMap(d=>d.cards), due=c=>c.due<=Date.now(), localDay=(t=Date.now())=>{let d=new Date(t);return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}`};
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const accuracy=r=>r.length?Math.round(100*r.filter(x=>x.rating>=2).length/r.length)+'%':'—';
function go(p){if(page==='math'&&mathSession?.running)endMath(false);clearInterval(practiceTimer);practiceTimer=null;if(session&&page==='study'&&p!=='study'&&!confirm('End this session? Completed reviews are saved.'))return;session=null;page=p;render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')home();else if(page==='deck')deckPage();else if(page==='import')importPage();else if(page==='study')study();else if(page==='stats')stats();else if(page==='settings')settings();else if(page==='practice')practice();else if(page==='quotes')quotePage();else if(page==='math')mathPage();}
function home(){const cs=all(),today=db.reviews.filter(r=>localDay(r.time)===localDay());const folders=[...new Set([...db.folders,...db.decks.map(d=>d.folder)])].sort();app.innerHTML=`<div class="row spread"><div><small>YOUR STUDY SPACE</small><h1>Ready to remember?</h1><p class="muted">Small steps. Stronger recall.</p></div><button class="primary" id="new">+ Import deck</button></div><div class="grid"><div class="metric"><small>Due now</small><strong>${cs.filter(due).length}</strong></div><div class="metric"><small>Total cards</small><strong>${cs.length}</strong></div><div class="metric"><small>Reviewed today</small><strong>${today.length}</strong></div></div><div class="panel"><div class="row spread"><h2>Library</h2><button id="foldernew">+ Folder</button></div><label for="filter">Folder</label><select id="filter"><option value="">All folders</option>${folders.map(f=>`<option value="${esc(f)}" ${folder===f?'selected':''}>${esc(f)}</option>`).join('')}</select><div id="decklist">${db.decks.filter(d=>!folder||d.folder===folder||d.folder.startsWith(folder+'/')).map(d=>`<div class="deck"><div class="grow"><small>${esc(d.folder)}</small><h3>${esc(d.name)}</h3><small>${d.cards.length} cards · ${d.cards.filter(due).length} due</small></div><button data-open="${esc(d.id)}">Open</button></div>`).join('')||'<p class="muted">No decks here yet. Import your first set.</p>'}</div></div>`;$('new').onclick=()=>go('import');$('filter').onchange=e=>{folder=e.target.value;home()};$('foldernew').onclick=()=>{let f=prompt('Folder name. Use / for nested folders, e.g. Speech/Impromptu');if(f?.trim()){f=f.trim();if(!db.folders.includes(f))db.folders.push(f);folder=f;save();home()}};app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{activeDeck=b.dataset.open;go('deck')})}
function deckPage(){const d=db.decks.find(x=>x.id===activeDeck);if(!d){go('home');return}app.innerHTML=`<button id="back">← Library</button><div class="row spread" style="margin-top:20px"><div><small>${esc(d.folder)}</small><h1>${esc(d.name)}</h1><p>${d.cards.length} cards · ${d.cards.filter(due).length} due</p></div><button id="rename">Edit deck</button></div><div class="panel"><h2>Study session</h2><div class="grid"><div><label for="mode">Mode</label><select id="mode"><option value="flash">Flashcards</option><option value="write">Written recall</option><option value="mc">Multiple choice</option><option value="cloze">Fill in the blank</option></select></div><div><label for="direction">Direction</label><select id="direction"><option value="forward">Front → back</option><option value="reverse">Back → front</option></select></div><div><label for="scope">Cards</label><select id="scope"><option value="all">All cards</option><option value="due">Due now</option><option value="missed">Previously missed</option></select></div></div><label for="limit">Session size</label><select id="limit"><option value="999999">Unlimited</option><option>20</option><option>10</option><option>50</option></select><p><button class="primary" id="start" ${d.cards.length?'':'disabled'}>Start studying</button></p></div><div class="panel"><div class="row spread"><h2>Cards</h2><div class="row"><button id="add">+ Add card</button><button id="append">Bulk add</button><button id="exportdeck">Export TSV</button></div></div><input id="search" placeholder="Search cards" aria-label="Search cards"><div id="cards"></div></div><button id="delete" class="danger">Delete deck</button>`;const show=()=>{const q=$('search').value.toLowerCase();$('cards').innerHTML=d.cards.filter(c=>(c.front+' '+c.back).toLowerCase().includes(q)).map(c=>`<div class="deck"><div class="grow answer"><strong>${esc(c.front)}</strong><br><small>${esc(c.back)}</small></div><button data-edit="${esc(c.id)}">Edit</button></div>`).join('');$('cards').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editCard(d,b.dataset.edit))};show();$('search').oninput=show;$('back').onclick=()=>go('home');$('rename').onclick=()=>{let n=prompt('Deck name',d.name);if(!n?.trim())return;let f=prompt('Folder path',d.folder);if(!f?.trim())return;d.name=n.trim();d.folder=f.trim();save();render()};$('add').onclick=()=>editCard(d);$('append').onclick=()=>{page='import';render();$('target').value=d.id;toggleTarget()};$('exportdeck').onclick=()=>download(d.name+'.tsv',d.cards.map(c=>[c.front,c.back].map(s=>s.replace(/\t/g,' ').replace(/\r?\n/g,' ')).join('\t')).join('\n'),'text/tab-separated-values');$('delete').onclick=()=>{if(confirm('Delete this deck and all its cards?')){db.decks=db.decks.filter(x=>x!==d);save();go('home')}};$('start').onclick=()=>start(d,$('mode').value,$('direction').value,$('scope').value,Number($('limit').value))}
function editCard(d,id){const c=d.cards.find(x=>x.id===id);app.innerHTML=`<h1>${c?'Edit':'New'} card</h1><div class="panel"><label for="front">Front</label><textarea id="front">${esc(c?.front||'')}</textarea><label for="backtext">Back</label><textarea id="backtext">${esc(c?.back||'')}</textarea><div class="row"><button class="primary" id="commit">Save card</button><button id="cancel">Cancel</button>${c?'<button class="danger" id="delcard">Delete card</button>':''}</div></div>`;$('commit').onclick=()=>{const f=$('front').value.trim(),b=$('backtext').value.trim();if(!f||!b){notify('Both sides are required.');return}if(c){c.front=f;c.back=b}else d.cards.push(card(f,b));save();render()};$('cancel').onclick=render;if(c)$('delcard').onclick=()=>{if(confirm('Delete this card?')){d.cards=d.cards.filter(x=>x!==c);save();render()}}}
function parse(text,magic=false){let result=[],skipped=0;for(let line of text.split(/\r?\n/)){line=line.trim().replace(/^[-*•]\s+/,'');if(!line||/^```/.test(line))continue;let sep=['\t',' :: ',' | ',' — ',' - '].find(s=>line.includes(s));if(!sep&&magic&&line.includes(': '))sep=': ';if(sep){let i=line.indexOf(sep),f=line.slice(0,i).trim(),b=line.slice(i+sep.length).trim();if(f&&b){result.push([f,b]);continue}}if(magic){let m=line.match(/^(.{2,90}?)\s+(?:is|are|means|refers to)\s+(.+)$/i);if(m){result.push([m[1],m[2]]);continue}}skipped++}return {result,skipped}}
function toggleTarget(){const isNew=$('target').value==='new';$('newfields').hidden=!isNew}
function importPage(){preview=[];app.innerHTML=`<button id="cancelimport">← Library</button><h1 style="margin-top:20px">Import flashcards</h1><p class="muted">Paste a whole ChatGPT deck, or turn your notes into reviewable cards.</p><div class="panel"><label for="target">Destination</label><select id="target"><option value="new">New deck</option>${db.decks.map(d=>`<option value="${esc(d.id)}">${esc(d.folder+' / '+d.name)}</option>`).join('')}</select><div id="newfields"><label for="deckname">Deck name</label><input id="deckname" placeholder="e.g. Real-world examples"><label for="foldername">Folder / subfolder</label><input id="foldername" list="folders" value="${esc(folder||'Speech')}"><datalist id="folders">${db.folders.map(f=>`<option value="${esc(f)}">`).join('')}</datalist></div><label for="raw">Paste text</label><textarea id="raw" placeholder="Courage&#9;Acting despite fear.&#10;Duty&#9;A moral responsibility."></textarea><div class="row"><button class="primary" id="parse">Preview bulk import</button><button id="magic">Magic import (offline)</button></div><p class="muted">Bulk: tab, spaced dash, double colon or pipe. Offline magic also recognizes simple definitions; it is rule-based, not AI.</p><details><summary>AI magic import (online)</summary><p>Open ChatGPT with a conversion prompt, then paste its response here. No API key is needed and no notes are sent automatically.</p><button id="aiprompt">Copy AI prompt + notes</button> <a href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT ↗</a></details></div><div id="preview"></div>`;$('target').onchange=toggleTarget;$('cancelimport').onclick=()=>go('home');$('parse').onclick=()=>makePreview(false);$('magic').onclick=()=>makePreview(true);$('aiprompt').onclick=async()=>{const text='Convert these notes into accurate flashcards. Output only tab-separated lines, one question and answer per line. Cover distinct concepts, do not invent facts, and do not use a header. Notes:\n'+$('raw').value;try{await navigator.clipboard.writeText(text);notify('Prompt copied. Paste into ChatGPT.')}catch{prompt('Copy this prompt:',text)}}}
function makePreview(magic){const p=parse($('raw').value,magic);preview=p.result;$('preview').innerHTML=`<div class="panel"><h2>${preview.length} cards recognized</h2><p class="muted">${p.skipped} nonempty lines skipped. Edit the source if needed. Exact duplicates are ignored.</p>${preview.slice(0,100).map(([f,b],i)=>`<div class="deck"><div class="grow answer"><strong>${esc(f)}</strong><br><small>${esc(b)}</small></div><button data-remove="${i}">Remove</button></div>`).join('')}${preview.length>100?'<p>Showing first 100; all recognized cards will import.</p>':''}<button class="primary" id="commitimport" ${preview.length?'':'disabled'}>Import ${preview.length} cards</button></div>`;$('preview').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.remove);preview.splice(i,1);b.closest('.deck').remove();$('commitimport').textContent=`Import ${preview.length} cards`;$('commitimport').disabled=!preview.length;$('preview').querySelectorAll('[data-remove]').forEach((x,j)=>x.dataset.remove=j)});$('commitimport').onclick=()=>{let d=db.decks.find(x=>x.id===$('target').value);if(!d){let n=$('deckname').value.trim(),f=$('foldername').value.trim();if(!n||!f){notify('Enter a deck name and folder.');return}d=deck(n,f,[]);db.decks.push(d);if(!db.folders.includes(f))db.folders.push(f)}let seen=new Set(d.cards.map(c=>JSON.stringify([c.front,c.back]))),added=0;for(let p of preview){let k=JSON.stringify(p);if(!seen.has(k)){d.cards.push(card(...p));seen.add(k);added++}}activeDeck=d.id;save();go('deck');notify(`${added} new cards imported.`)}}
function start(d,mode,dir,scope,limit){let cards=shuffle(d.cards.filter(c=>scope==='all'||(scope==='due'&&due(c))||(scope==='missed'&&db.reviews.slice().reverse().find(r=>r.cardId===c.id)?.rating<2))).sort((a,b)=>scope==='due'?a.due-b.due:0).slice(0,limit);if(!cards.length){notify('No matching cards. Choose All cards to practice anyway.');return}if(mode==='mc'&&new Set(d.cards.map(c=>dir==='reverse'?c.front:c.back)).size<2){notify('Multiple choice needs at least two different answers.');return}session={deck:d,mode,dir,queue:cards.map(c=>({c,attempt:0})),total:cards.length,done:0,ratings:[],revealed:false,typed:'',choice:null,choices:null,blank:null,scope};page='study';render();window.scrollTo(0,0)}
function sides(c){return session.dir==='reverse'?[c.back,c.front]:[c.front,c.back]}
function study(){const s=session;if(!s){go('home');return}if(!s.queue.length){app.innerHTML=`<div class="panel" style="text-align:center"><small>SESSION COMPLETE</small><h1>Nice work.</h1><p>${s.done} unique cards completed · ${s.ratings.length} attempts</p><div class="grid"><div class="metric"><small>Recall accuracy</small><strong>${accuracy(s.ratings)}</strong></div><div class="metric"><small>Reviews saved</small><strong>${s.ratings.length}</strong></div></div><p><button class="primary" id="finish">Back to deck</button></p></div>`;$('finish').onclick=()=>{session=null;go('deck')};return}let item=s.queue[0],c=item.c,[q,a]=sides(c);if(s.mode==='cloze'){if(!s.blank){let words=a.match(/[\p{L}\p{N}]+/gu)||[];let candidates=words.filter(w=>w.length>=5);s.blank=shuffle(candidates.length?candidates:words)[0]||a}q=q+'\n\n'+a.replace(s.blank,'_____');a=s.blank;}if(s.mode==='mc'&&!s.choices){let other=[...new Set(s.deck.cards.map(x=>sides(x)[1]).filter(x=>x!==a))];s.choices=shuffle([a,...shuffle(other).slice(0,3)])}app.innerHTML=`<div class="row spread"><button id="exit">← Exit session</button><small>${esc(s.deck.name)} · ${s.done}/${s.total} completed</small></div><div class="progress"><i style="width:${100*s.done/s.total}%"></i></div><p class="muted">${s.queue.length} remaining · ${item.attempt?'Retry card':'Recall before revealing'}</p><button class="panel studycard" id="flip"><small>${s.revealed?'ANSWER':'QUESTION'}</small><span>${esc(s.revealed?a:q)}</span><small>${s.mode==='flash'?'Tap to flip':s.revealed?'Original question: '+esc(q):''}</small></button>${['write','cloze'].includes(s.mode)?`<div class="panel"><label for="typed">Your answer</label><textarea id="typed" ${s.revealed?'readonly':''}>${esc(s.typed)}</textarea>${s.revealed?'<p>Compare your answer with the card and rate yourself. Exact matching would unfairly reject paraphrases.</p>':'<button id="reveal" class="primary">Reveal answer</button>'}</div>`:''}${s.mode==='mc'?`<div class="choices">${s.choices.map((x,i)=>`<button data-choice="${i}" ${s.revealed?'disabled':''} class="${s.revealed?(x===a?'correct':x===s.choice?'wrong':''):''}">${esc(x)}</button>`).join('')}</div>${s.revealed?`<p>${s.choice===a?'Correct!':'Not quite. Review the correct answer above.'}</p>`:''}`:''}${s.revealed&&s.mode==='mc'?`<button class="primary nextquiz" id="nextquiz">Next question →</button>`:s.revealed?`<div class="rating">${['Again','Hard','Good','Easy'].map((x,i)=>`<button data-rate="${i}" ${s.mode==='mc'&&((s.choice!==a&&i>0)||(s.choice===a&&i<2))?'disabled':''}>${x}<small>${i+1} · ${['retry','shorter','normal','longer'][i]}</small></button>`).join('')}</div>`:''}<p class="muted">${s.mode==='flash'?'Space: flip · Swipe left: Again · Swipe right: Good · ':''}1–4: rate after revealing.</p>`;$('exit').onclick=()=>go('deck');if($('nextquiz'))$('nextquiz').onclick=()=>rate(s.choice===sides(c)[1]?2:0);$('flip').onclick=()=>{if(s.mode==='flash'){s.revealed=!s.revealed;study()}};if(['write','cloze'].includes(s.mode)&&!s.revealed){$('typed').oninput=e=>s.typed=e.target.value;$('reveal').onclick=()=>{s.revealed=true;study()}}app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{s.choice=s.choices[Number(b.dataset.choice)];s.revealed=true;study()});app.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>rate(Number(b.dataset.rate)));let x,y;$('flip').addEventListener('touchstart',e=>{x=e.changedTouches[0].clientX;y=e.changedTouches[0].clientY},{passive:true});$('flip').addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(s.mode==='flash'&&s.revealed&&Math.abs(dx)>70&&Math.abs(dx)>Math.abs(dy)*1.5)rate(dx>0?2:0)},{passive:true})}
function schedule(c,r,now=Date.now()){let old=c.interval||0;c.reps++;if(r===0){c.lapses++;c.interval=10/1440}else if(r===1)c.interval=Math.max(1,old*1.2);else if(r===2)c.interval=Math.max(1,old*2.2);else c.interval=Math.max(4,old*3.2);c.interval=Math.min(c.interval,365);c.due=now+c.interval*DAY}
function rate(r){let s=session;if(!s?.revealed||!s.queue.length)return;let item=s.queue[0],c=item.c;if(s.mode==='mc'&&((s.choice!==sides(c)[1]&&r!==0)||(s.choice===sides(c)[1]&&r<2)))return;s.queue.shift();schedule(c,r);let review={time:Date.now(),cardId:c.id,deckId:s.deck.id,rating:r,mode:s.mode};db.reviews.push(review);s.ratings.push(review);if(r===0&&item.attempt<2)s.queue.splice(Math.min(3,s.queue.length),0,{c,attempt:item.attempt+1});else s.done++;save();Object.assign(s,{revealed:false,typed:'',choice:null,choices:null,blank:null});study()}
function stats(){let cs=all(),r=db.reviews,today=r.filter(x=>localDay(x.time)===localDay()),days=Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString(undefined,{weekday:'short',day:'numeric'}),n:r.filter(x=>localDay(x.time)===localDay(d.getTime())).length}}),max=Math.max(1,...days.map(d=>d.n));app.innerHTML=`<h1>Your progress</h1><p class="muted">Accuracy counts Good and Easy ratings as successful recall; Hard and Again as not yet secure.</p><div class="grid">${[['All time questions answered',r.length],['Today',today.length],['Recall accuracy',accuracy(r)],['Mastered (21+ day interval)',cs.filter(c=>c.interval>=21).length],['Learning',cs.filter(c=>c.reps&&c.interval<21).length],['New',cs.filter(c=>!c.reps).length]].map(([k,v])=>`<div class="metric"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><div class="panel"><h2>Daily goal</h2><p>${today.length} / ${Number(db.goal)||50} reviews today</p><div class="progress"><i style="width:${Math.min(100,today.length/(Number(db.goal)||50)*100)}%"></i></div></div><div class="panel"><h2>Last seven days</h2>${days.map(d=>`<div class="day"><small>${esc(d.label)}</small><div class="bar"><i style="width:${100*d.n/max}%"></i></div><small>${d.n}</small></div>`).join('')}</div><div class="panel"><h2>By deck</h2>${db.decks.map(d=>`<div class="deck"><div><strong>${esc(d.name)}</strong><br><small>${d.cards.filter(c=>c.interval>=21).length}/${d.cards.length} mastered · ${d.cards.filter(due).length} due</small></div><strong>${accuracy(r.filter(x=>x.deckId===d.id))}</strong></div>`).join('')}</div>`}
function download(name,text,type='application/json'){let url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validate(x){return x&&x.version===1&&['light','dark','system'].includes(x.theme)&&Array.isArray(x.folders)&&x.folders.every(f=>typeof f==='string')&&Array.isArray(x.decks)&&x.decks.every(d=>typeof d.id==='string'&&typeof d.name==='string'&&typeof d.folder==='string'&&Array.isArray(d.cards)&&d.cards.every(c=>typeof c.id==='string'&&typeof c.front==='string'&&typeof c.back==='string'&&['due','interval','reps','lapses'].every(k=>Number.isFinite(c[k])&&c[k]>=0)))&&Array.isArray(x.reviews)&&x.reviews.every(r=>Number.isFinite(r.time)&&[0,1,2,3].includes(r.rating)&&typeof r.cardId==='string'&&typeof r.deckId==='string')}
function settings(){app.innerHTML=`<h1>Settings</h1><div class="panel"><h2>Appearance</h2><label for="goal">Daily review goal</label><input id="goal" type="number" min="1" max="10000" value="${Number(db.goal)||50}"><label for="theme">Theme</label><select id="theme">${['system','light','dark'].map(t=>`<option ${db.theme===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="panel"><h2>Data & backups</h2><p>Cards and review history are saved in local browser storage. Devices do not automatically sync. Export regularly, especially before clearing Safari data.</p><button class="primary" id="backup">Export complete backup</button><label for="restore">Restore backup (replaces local library)</label><input type="file" id="restore" accept=".json,application/json"><p class="muted">${storageOK?'Local storage available.':'Storage write failed. Export immediately.'}</p></div><div class="panel"><h2>Offline installation</h2><p id="offline">Checking offline support…</p><p>On iPad: open the hosted URL in Safari, tap Share → Add to Home Screen. Keep a backup outside the app.</p></div><div class="panel"><h2>Keyboard shortcuts</h2><p>Space flips flashcards. 1–4 rate a revealed answer. Arrow left/right rates Again/Good in flashcard mode. In written mode use the Reveal button; in multiple choice select an answer first.</p></div>`;$('goal').onchange=e=>{db.goal=Math.max(1,Math.min(10000,Math.round(Number(e.target.value)||50)));e.target.value=db.goal;save()};$('theme').onchange=e=>{db.theme=e.target.value;theme();save()};$('backup').onclick=()=>download('recall-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(db,null,2));$('restore').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;let x=JSON.parse(await f.text());if(!validate(x))throw Error('Invalid Recall backup');if(confirm('Replace all local decks and review history with this backup?')){db=x;save();theme();go('home');notify('Backup restored.')}}catch(err){notify('Could not restore: '+err.message)}};if('serviceWorker'in navigator&&isSecureContext){navigator.serviceWorker.getRegistration().then(reg=>{if($('offline'))$('offline').textContent=reg?.active?'Offline cache installed. Open the app once online before travelling.':'Offline cache not active yet. Reload after the first online visit.'})}else $('offline').textContent='Offline installation requires HTTPS or localhost.'}
let practiceTimer=null;
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelector('.brand').onclick=e=>{e.preventDefault();go('home')};document.addEventListener('keydown',e=>{if(page!=='study'||!session?.queue.length||/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'&&session.mode==='flash'&&(document.activeElement?.tagName!=='BUTTON'||document.activeElement.id==='flip')){e.preventDefault();session.revealed=!session.revealed;study()}else if(session.mode==='mc'&&!session.revealed&&/^[1-4]$/.test(e.key)){let b=app.querySelector('[data-choice="'+(Number(e.key)-1)+'"]');if(b){e.preventDefault();b.click()}}else if(session.mode==='mc'&&session.revealed&&e.key==='Enter'){e.preventDefault();$('nextquiz')?.click()}else if(session.revealed&&/^[1-4]$/.test(e.key)){e.preventDefault();rate(Number(e.key)-1)}else if(session.revealed&&session.mode==='flash'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();rate(e.key==='ArrowLeft'?0:2)}});if('serviceWorker'in navigator&&isSecureContext)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>r.update()).catch(console.warn);render();

const speechBank=[['Duty','Courage','Belonging','Integrity','Hope','Silence','Identity','Ambition','Patience','Freedom','Curiosity','Regret','Trust','Responsibility','Wisdom'],['A double-edged sword','A blessing in disguise','The road less travelled','The price of success','The grass is always greener','A stitch in time saves nine','Actions speak louder than words','The ends justify the means','The tip of the iceberg','Nothing ventured, nothing gained'],['The unexamined life is not worth living.','No man is an island.','Power concedes nothing without a demand.','All the world’s a stage.','Well done is better than well said.','The pen is mightier than the sword.']];
const motionBank={Junior:['THW ban advertising aimed at children','THBT schools should prioritize curiosity over competition','THW abolish homework in elementary school','THP a world without social media','THW make public transport free','THBT competitive sports do more good than harm for children'],Advanced:['THR the glorification of overwork','THBT governments should prioritize rehabilitation over punishment','TH as a young person would pursue passion over prestige','THW prohibit political microtargeting','THP a world in which people do not know the wealth of their peers','THBT developing countries should prioritize economic growth over environmental protection','THW give Indigenous communities veto power over resource projects on their traditional lands','THR the commercialization of higher education'],Senior:['THBT social movements should prioritize institutional reform over cultural change','THP a weak democracy to a benevolent dictatorship','THBT states should prioritize strategic autonomy over integration into major power blocs','THR the narrative that personal identity should be rooted in national identity','THBT international institutions should condition development assistance on democratic reforms','TH as a social movement would reject corporate sponsorship','THP a world where people are unaware of their own relative social status']};
const drills={mechanism:['Argument mechanism','Build a causal chain: actor → incentive → behaviour → outcome. Explain why each link is likely, compare to the other side, and preempt the weakest link.'],weighing:['Weighing','Build a comparison between two plausible impacts. Compare magnitude, probability, timeframe, reversibility and who is affected. Explain why your chosen metric matters in this round.'],framing:['Framing','Identify the motion type, actor, status quo, counterfactual, stakeholders and burdens. Explain the fairest interpretation and the decisive question for the judge.'],rebuttal:['Rebuttal','Construct the strongest opposing argument, identify its weakest assumption, challenge the mechanism and give an even-if comparison.'],whip:['Whip & clashes','Identify two central clashes. Compare both sides, rebuild your case and explain why your contribution wins. In BP closing, distinguish your extension from opening.'],constructive:['Full constructive','Develop two distinct arguments with mechanisms, impacts, comparative analysis and preemption.']};
const rubric={speech:['Relevance: directly interpret the assigned prompt.','Originality: challenge a conventional belief.','Structure: clear thesis and distinct insights.','Storytelling: setting, conflict, decision, outcome, lesson.','Delivery: pace, eye contact, emphasis and pauses (self-assess if using text).'],mechanism:['Name the actor and their incentive.','Explain why behaviour changes relative to the counterfactual.','Explain intermediate causal links rather than asserting the impact.','Identify a plausible obstacle and answer it.'],weighing:['Compare both sides explicitly.','Justify the metric you prioritize.','Discuss probability and magnitude.','Use an even-if comparison.'],framing:['Identify actor, motion type and burdens.','Define the status quo and alternative.','Prioritize relevant stakeholders.','Explain what decides the round.'],rebuttal:['Represent the opposing claim fairly.','Identify and challenge a key assumption.','Explain why your response matters.','Compare residual impacts even if their claim is partly true.'],whip:['Organize by clashes rather than speaker order.','Rebuild your strongest material.','Compare impacts and contribution.','Avoid new substantive arguments in whip.'],constructive:['Use two distinct mechanisms.','Explain stakeholder incentives.','Develop impacts comparatively.','Preempt likely responses.']};
let trainingTab='speech',trainingPrompt='',trainingNotes='',trainingType='mechanism',trainingLevel='Advanced',trainingSide='Proposition';
function practice(){clearInterval(practiceTimer);practiceTimer=null;app.innerHTML=`<small>TRAINING STUDIO</small><h1>Debate &amp; Public Speaking</h1><p class="muted">Build ideas, speak with confidence, and sharpen your comparisons.</p><div class="row training-tabs">${[['speech','Public speaking'],['debate','Debate drills'],['tutor','AI tutor']].map(([k,n])=>`<button data-training="${k}" class="${trainingTab===k?'primary':''}">${n}</button>`).join('')}</div><div id="trainingbody"></div>`;app.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>{trainingNotes=$('notes')?.value??trainingNotes;trainingTab=b.dataset.training;practice()});if(trainingTab==='tutor'){tutorPage();return}const speech=trainingTab==='speech';$('trainingbody').innerHTML=`<div class="panel">${speech?'<h2>Impromptu speaking</h2><p class="muted">Choose one of three prompts. Aim for a 3–5 minute speech after 2 minutes of prep.</p>':`<h2>Debate training</h2><div class="grid"><div><label for="drill">Skill</label><select id="drill">${Object.entries(drills).map(([k,v])=>`<option value="${k}" ${k===trainingType?'selected':''}>${v[0]}</option>`).join('')}</select></div><div><label for="level">Difficulty</label><select id="level">${Object.keys(motionBank).map(k=>`<option ${k===trainingLevel?'selected':''}>${k}</option>`).join('')}</select></div><div><label for="side">Side</label><select id="side">${['Proposition','Opposition'].map(k=>`<option ${k===trainingSide?'selected':''}>${k}</option>`).join('')}</select></div></div><p id="instruction" class="muted"></p>`}<div id="promptbox" class="promptbox"></div><button id="generate">New ${speech?'topics':'motion'}</button><div class="grid"><div><label for="minutes">Timer (minutes)</label><input id="minutes" type="number" min="1" max="120" value="${speech?2:5}"></div><div><label>Quick timers</label><div class="row"><button data-min="2">2 min</button><button data-min="5">5 min</button><button data-min="8">8 min</button><button data-min="15">15 min</button></div></div></div><div id="clock" class="timer" aria-live="off">02:00</div><div class="row"><button class="primary" id="timerstart">Start</button><button id="timerpause">Pause</button><button id="timerreset">Reset</button></div><label for="notes">Your prep / response</label><textarea id="notes" placeholder="Write your own ideas first…">${esc(trainingNotes)}</textarea><div class="row"><button id="feedback">Review with AI tutor</button><button id="checklist">Show self-check</button></div><div id="selfcheck"></div></div>`;let left=0,deadline=0;function draw(){ $('clock').textContent=String(Math.floor(left/60)).padStart(2,'0')+':'+String(left%60).padStart(2,'0') }function stop(){clearInterval(practiceTimer);practiceTimer=null;$('timerstart').disabled=false}function reset(){stop();left=Math.round(Math.max(1,Math.min(120,Number($('minutes').value)||2))*60);draw()}function generate(){if(speech){let picks=speechBank.map(a=>shuffle(a)[0]);trainingPrompt=picks[0];$('promptbox').innerHTML=picks.map((p,i)=>`<button class="topic ${i===0?'chosen':''}" data-topic="${i}"><small>${['Concept','Saying','Quotation'][i]}</small><strong>${esc(p)}</strong></button>`).join('');$('promptbox').querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{trainingPrompt=picks[Number(b.dataset.topic)];$('promptbox').querySelectorAll('button').forEach(x=>x.classList.toggle('chosen',x===b))})}else{trainingPrompt=shuffle(motionBank[trainingLevel])[0];$('promptbox').innerHTML=`<h2>${esc(trainingPrompt)}</h2><small>${esc(trainingSide)}</small>`;$('instruction').textContent=drills[trainingType][1]}reset()}if(!speech){$('drill').onchange=e=>{trainingType=e.target.value;$('instruction').textContent=drills[trainingType][1];$('selfcheck').textContent=''};$('level').onchange=e=>{trainingLevel=e.target.value;generate()};$('side').onchange=e=>{trainingSide=e.target.value;$('promptbox').querySelector('small').textContent=trainingSide}}$('generate').onclick=generate;$('minutes').onchange=reset;app.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{$('minutes').value=b.dataset.min;reset()});$('timerreset').onclick=reset;$('timerpause').onclick=()=>{if(practiceTimer){left=Math.max(0,Math.ceil((deadline-Date.now())/1000));stop();draw()}};$('timerstart').onclick=()=>{if(!left)reset();deadline=Date.now()+left*1000;$('timerstart').disabled=true;practiceTimer=setInterval(()=>{left=Math.max(0,Math.ceil((deadline-Date.now())/1000));draw();if(!left){stop();notify('Time is up!')}},250)};$('checklist').onclick=()=>{$('selfcheck').innerHTML=`<h3>Self-assessment</h3>${rubric[speech?'speech':trainingType].map(t=>`<label class="check"><input type="checkbox">${esc(t)}</label>`).join('')}`};$('feedback').onclick=()=>{trainingNotes=$('notes').value;trainingTab='tutor';practice()};generate()}
function tutorPage(){const kind=trainingPrompt?(speechBank.flat().includes(trainingPrompt)?'speech':trainingType):'speech';$('trainingbody').innerHTML=`<div class="panel"><h2>AI tutor · ChatGPT assisted</h2><p>Get detailed feedback on your work. This app prepares the coaching prompt locally; you choose whether to share it with ChatGPT. No API key, automatic upload or embedded AI.</p><label for="coachskill">Coaching focus</label><select id="coachskill">${[['speech','Impromptu speech'],...Object.entries(drills).map(([k,v])=>[k,v[0]])].map(([k,n])=>`<option value="${k}" ${kind===k?'selected':''}>${n}</option>`).join('')}</select><label for="coachprompt">Topic or motion</label><input id="coachprompt" value="${esc(trainingPrompt)}"><label for="notes">Your speech, argument or prep</label><textarea id="notes">${esc(trainingNotes)}</textarea><label for="coachside">Side / role / context (optional)</label><input id="coachside" value="${esc(kind==='speech'?'':trainingSide)}"><div class="row"><button class="primary" id="copycoach">Copy coaching prompt</button><a href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT ↗</a></div><p class="muted">Paste the copied prompt into ChatGPT. Avoid including personal information. Text feedback cannot assess actual voice or eye contact.</p><details><summary>Offline coaching checklist</summary><div id="coachcheck"></div></details></div>`;function check(){ $('coachcheck').innerHTML=rubric[$('coachskill').value].map(t=>`<label class="check"><input type="checkbox">${esc(t)}</label>`).join('') }$('coachskill').onchange=check;check();$('copycoach').onclick=async()=>{const k=$('coachskill').value;const t=`Act as a rigorous but encouraging junior competitive debate and public speaking coach. Focus: ${k}. Topic: ${$('coachprompt').value}. Context: ${$('coachside').value}. My own work:\n${$('notes').value}\nAssess the work against these criteria:\n${rubric[k].join('\n')}\nGive specific feedback, a score out of 10 for each relevant criterion, and one targeted retry drill. Do not invent evidence or claim to assess delivery from text. If I have not supplied a response, ask me to attempt the drill first.`;try{await navigator.clipboard.writeText(t);notify('Coaching prompt copied. Open ChatGPT and paste.')}catch{const x=document.createElement('textarea');x.value=t;$('trainingbody').append(x);x.select();notify('Select and copy the prompt below.')}}}
const quotes=[['Power concedes nothing without a demand.','Frederick Douglass · 1857 speech','Justice, activism'],['No man is an island.','John Donne · Meditation XVII','Community, empathy'],['The unexamined life is not worth living.','Socrates, in Plato’s Apology (translation)','Wisdom, reflection'],['Well done is better than well said.','Benjamin Franklin · Poor Richard’s Almanack','Integrity, action'],['All the world’s a stage.','William Shakespeare · As You Like It','Identity, society'],['Brevity is the soul of wit.','William Shakespeare · Hamlet','Speaking, clarity'],['What’s past is prologue.','William Shakespeare · The Tempest','History, change'],['The pen is mightier than the sword.','Edward Bulwer-Lytton · Richelieu','Ideas, persuasion'],['Hope is the thing with feathers.','Emily Dickinson · poem opening','Hope, resilience'],['A foolish consistency is the hobgoblin of little minds.','Ralph Waldo Emerson · Self-Reliance','Adaptability, thinking'],['Our life is frittered away by detail.','Henry David Thoreau · Walden','Focus, priorities'],['I think, therefore I am.','René Descartes · Discourse on the Method (translation)','Knowledge, identity'],['Progress is not the same thing as purpose.','Recall · original reflection','Ambition, life'],['A strong argument explains the bridge between a claim and its consequence.','Recall · original reflection','Debate, mechanism'],['The point of a pause is not silence; it is space for meaning.','Recall · original reflection','Public speaking'],['You can revise your beliefs without surrendering your values.','Recall · original reflection','Growth, humility'],['Confidence can follow action rather than precede it.','Recall · original reflection','Courage, life'],['A fair comparison begins by taking the other side seriously.','Recall · original reflection','Debate, weighing'],['A story becomes meaningful when we understand the choice at its centre.','Recall · original reflection','Storytelling'],['Do not confuse being heard with being understood.','Recall · original reflection','Communication'],['What we measure is not always what matters.','Recall · original reflection','Success, values'],['The strongest speaker makes difficult ideas clear.','Recall · original reflection','Public speaking']];
function quotePage(){app.innerHTML=`<small>WORDS WORTH REMEMBERING</small><h1>Quote library</h1><p class="muted">Find hooks for speeches, debate and everyday reflection.</p><div class="panel quotehero"><div id="featured"></div><div class="row"><button class="primary" id="newquote">Random quote</button><button id="copyquote">Copy quote</button></div></div><label for="qsearch">Search by quote, author or theme</label><input id="qsearch" placeholder="e.g. courage, justice, speaking"><div id="qlist"></div>`;let q;function next(){q=shuffle(quotes.filter(x=>x!==q))[0];$('featured').innerHTML=`<blockquote>${esc(q[0])}</blockquote><p>${esc(q[1])}</p><small>${esc(q[2])}</small>`}function list(){let k=$('qsearch').value.toLowerCase();$('qlist').innerHTML=quotes.filter(x=>x.join(' ').toLowerCase().includes(k)).map(x=>`<div class="panel"><h3>${esc(x[0])}</h3><p class="muted">${esc(x[1])} · ${esc(x[2])}</p></div>`).join('')||'<p>No matching quotes.</p>'}$('newquote').onclick=next;$('copyquote').onclick=async()=>{try{await navigator.clipboard.writeText(q[0]+' — '+q[1]);notify('Quote copied.')}catch{prompt('Copy quote:',q[0]+' — '+q[1])}};$('qsearch').oninput=list;next();list()}

// Mental math studio — independent from flashcard scheduling.
const mathTopics={add:'Addition',sub:'Subtraction',mul:'Multiplication',div:'Division',percent:'Percentages',decimal:'Decimals',convert:'Fraction / decimal / percent conversions',units:'Metric & time conversions',fraction:'Fraction arithmetic',mod:'Modulo / remainders',lcm:'LCM',gcf:'GCF',prime:'Prime or composite',factor:'Factors & divisibility',power:'Powers & roots',signed:'Negative numbers',order:'Order of operations',ratio:'Ratios & proportions',estimate:'Estimation & rounding',algebra:'Missing numbers',financial:'Discounts, tax & markup'};
const ri=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
const gcd=(a,b)=>b?gcd(b,a%b):Math.abs(a);
const isPrime=n=>n>1&&Array.from({length:Math.floor(Math.sqrt(n))-1},(_,i)=>i+2).every(d=>n%d!==0);
const nice=n=>Number(n.toFixed(8));
function mathQuestion(topic,level){const L=Number(level), max=[0,30,150,999][L], a=ri(2,max), b=ri(2,max), x=ri(2,[0,12,25,99][L]), y=ri(2,[0,12,25,99][L]);const q=(prompt,answer,tip)=>({topic,prompt,answer,tip});let d,n,p,k,f,g,m;
 switch(topic){
 case 'add':return q(`${a} + ${b}`,a+b,`Round ${b} to a convenient ten, then compensate.`);
 case 'sub':return q(`${L===1?Math.max(a,b):a} − ${L===1?Math.min(a,b):b}`,L===1?Math.abs(a-b):a-b,'Count up or subtract a rounded number and adjust.');
 case 'mul':return q(`${x} × ${y}`,x*y,`Split ${y} into place values and distribute.`);
 case 'div':return q(`${x*y} ÷ ${x}`,y,'Think of the inverse multiplication fact.');
 case 'percent':p=shuffle(L===1?[10,20,25,50,75]:L===2?[5,12.5,15,35,62.5,80]:[2.5,17.5,37.5,65,87.5,125])[0];n=ri(2,max)*4;return q(`${p}% of ${n}`,nice(p*n/100),'Break the percentage into familiar fractions or 10% and 1%.');
 case 'decimal':d=L===1?10:100;f=a/d;g=b/d;k=ri(0,L===1?1:2);return k===0?q(`${f} + ${g}`,nice(f+g),'Align decimal places.'):k===1?q(`${f} − ${g}`,nice(f-g),'Subtract as integers, then restore the decimal.'):q(`${f} × ${y}`,nice(f*y),'Multiply as integers, then restore decimal places.');
 case 'convert':d=shuffle(L===1?[2,4,5,10]:[3,4,5,8,16,20,25,40])[0];n=ri(1,d-1);k=ri(0,2);return k===0?q(`${n}/${d} as a decimal (round to 4 decimal places if needed)`,nice(Math.round(n/d*10000)/10000),'Divide numerator by denominator.'):k===1?q(`${n}/${d} as a percent (number only; round to 2 decimal places)`,Math.round(n/d*10000)/100,'Multiply the fraction by 100.'):q(`${nice(n/d*100)}% as a decimal (round to 4 decimal places if needed)`,Math.round(n/d*10000)/10000,'Divide by 100.');
 case 'units':return shuffle([q(`${x} km = ? m`,x*1000,'1 km = 1000 m.'),q(`${x*25} cm = ? m`,x/4,'Divide centimetres by 100.'),q(`${x} hours = ? minutes`,x*60,'Multiply by 60.'),q(`${x*125} mL = ? L`,x/8,'Divide millilitres by 1000.'),q(`${x} kg = ? g`,x*1000,'Multiply kilograms by 1000.'),q(`${x*15} minutes = ? hours`,x/4,'Divide minutes by 60.')])[0];
 case 'fraction':d=ri(2,L===1?8:15);f=ri(1,d);g=ri(1,d);k=ri(0,L===1?1:3);let num,den,op; if(k===0){num=f+g;den=d;op='+'}else if(k===1){num=f-g;den=d;op='−'}else if(k===2){num=f*g;den=d*d;op='×'}else{num=f;den=g;op='÷'}m=gcd(num,den);return q(`${f}/${d} ${op} ${g}/${d} (fraction or decimal)`,`${num/m}/${den/m}`,'Use common denominators for +/−; multiply fractions directly; divide by multiplying the reciprocal.');
 case 'mod':return q(`${a} mod ${x} (remainder)`,a%x,`Find the largest multiple of ${x} no greater than ${a}.`);
 case 'lcm':f=x;g=y;return q(`LCM(${f}, ${g})`,f*g/gcd(f,g),'List multiples or use product ÷ GCF.');
 case 'gcf':d=ri(2,L*5);f=x*d;g=y*d;return q(`GCF(${f}, ${g})`,gcd(f,g),'Use common prime factors or the Euclidean algorithm.');
 case 'prime':n=ri(2,max);return q(`Is ${n} prime or composite?`,isPrime(n)?'prime':'composite','Test divisibility by primes up to the square root.');
 case 'factor':d=ri(2,12);n=ri(2,max);return q(`Is ${n} divisible by ${d}? (yes/no)`,n%d===0?'yes':'no',`Check whether division by ${d} has remainder zero.`);
 case 'power':n=ri(2,L===1?12:L===2?25:40);return Math.random()<.5?q(`${n}²`,n*n,'Use (a+b)² = a² + 2ab + b².'):q(`√${n*n}`,n,'Recall perfect squares.');
 case 'signed':return q(`−${a} + ${b} − ${x}`, -a+b-x,'Combine positive and negative terms separately.');
 case 'order':return q(`${a} − ${x} × ${y} + ${b}`,a-x*y+b,'Multiply before adding or subtracting.');
 case 'ratio':d=ri(2,12);return q(`${x}:${y} = ${x*d}:?`,y*d,'Multiply both sides of the ratio by the same factor.');
 case 'estimate':d=L===1?10:100;n=ri(d, max*d);return q(`Round ${n} to nearest ${d}`,Math.round(n/d)*d,'Look at the digit immediately to the right of the rounding place.');
 case 'algebra':return q(`${x} × ? + ${a} = ${x*y+a}`,y,'Undo addition, then undo multiplication.');
 case 'financial':p=shuffle([5,10,15,20,25,30,40,50])[0];n=ri(2,max)*4;k=ri(0,2);return q(`$${n} after ${p}% ${['discount','tax','markup'][k]} (dollars only)`,nice(n*(1+(k===0?-1:1)*p/100)),'Multiply by 1 minus the discount rate, or 1 plus the tax/markup rate.');
 default:return q('2 + 2',4,'Add the two numbers.');}}
function numericMath(s){s=String(s).trim().replace(/,/g,'');if(/^[-+]?\d+\s*\/\s*[-+]?\d+$/.test(s)){let [a,b]=s.split('/').map(Number);return b?a/b:NaN}return /^[-+]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)?Number(s):NaN}
function mathCorrect(input,answer){if(['prime','composite','yes','no'].includes(answer))return input.trim().toLowerCase()===answer;let a=numericMath(input),b=numericMath(answer);return Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)<1e-7}
let mathSession=null,mathTimer=null,mathConfig={topics:Object.keys(mathTopics),level:2,count:20,minutes:0},mathRetry=null;
function mathHistory(){return Array.isArray(db.mathHistory)?db.mathHistory:[]}
function mathPage(){if(mathSession?.running){mathDraw();return}const h=mathHistory(),correct=h.filter(r=>r.correct).length;app.innerHTML=`<small>NUMBER FLUENCY STUDIO</small><h1>Mental Math</h1><p class="muted">Train speed and accuracy without a calculator. Pick topics or mix everything.</p><div class="grid"><div class="metric"><small>All-time answers</small><strong>${h.length}</strong></div><div class="metric"><small>Accuracy</small><strong>${h.length?Math.round(correct/h.length*100)+'%':'—'}</strong></div><div class="metric"><small>Average seconds</small><strong>${h.length?(h.reduce((s,r)=>s+r.seconds,0)/h.length).toFixed(1):'—'}</strong></div></div><div class="panel"><div class="row spread"><h2>Configure a drill</h2><div class="row"><button id="mathall">Select all</button><button id="mathnone">Clear</button></div></div><div class="math-topics">${Object.entries(mathTopics).map(([k,v])=>`<label class="check"><input type="checkbox" value="${k}" ${mathConfig.topics.includes(k)?'checked':''}>${v}</label>`).join('')}</div><div class="grid"><div><label for="mathlevel">Difficulty</label><select id="mathlevel">${['Easy','Medium','Hard'].map((v,i)=>`<option value="${i+1}" ${mathConfig.level===i+1?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="mathcount">Question limit</label><select id="mathcount">${[10,20,50,100,0].map(n=>`<option value="${n}" ${mathConfig.count===n?'selected':''}>${n||'Unlimited'}</option>`).join('')}</select></div><div><label for="mathminutes">Time limit</label><select id="mathminutes">${[0,1,2,3,5,10].map(n=>`<option value="${n}" ${mathConfig.minutes===n?'selected':''}>${n?n+' min':'Untimed'}</option>`).join('')}</select></div></div><p><button class="primary" id="mathstart">Start training</button></p></div><div class="panel"><h2>Review & tutor</h2><div class="row"><button id="mathretry" ${h.some(r=>!r.correct)?'':'disabled'}>Retry mistakes</button><button id="mathtutor">AI tutor</button><button id="mathexport" ${h.length?'':'disabled'}>Export history</button></div><div id="mathdetails"></div></div><div class="panel"><h2>Topic performance</h2>${Object.entries(mathTopics).map(([k,v])=>{let r=h.filter(t=>t.topic===k);return r.length?`<div class="deck"><span>${v}</span><small>${r.filter(t=>t.correct).length}/${r.length} correct · ${(r.reduce((s,t)=>s+t.seconds,0)/r.length).toFixed(1)} s</small></div>`:''}).join('')||'<p class="muted">Complete a drill to see your strengths and weaknesses.</p>'}</div>`;
 const checks=()=>[...app.querySelectorAll('.math-topics input')];$('mathall').onclick=()=>checks().forEach(c=>c.checked=true);$('mathnone').onclick=()=>checks().forEach(c=>c.checked=false);$('mathstart').onclick=()=>{let topics=checks().filter(c=>c.checked).map(c=>c.value);if(!topics.length){notify('Choose at least one topic.');return}mathConfig={topics,level:+$('mathlevel').value,count:+$('mathcount').value,minutes:+$('mathminutes').value};startMath()};$('mathretry').onclick=()=>{let seen=new Set();mathRetry=h.slice().reverse().filter(r=>{let key=r.prompt;if(seen.has(key))return false;seen.add(key);return !r.correct}).slice(0,50);if(mathRetry.length)startMath(mathRetry);else notify('No unresolved mistakes. Great work!')};$('mathtutor').onclick=mathTutor;$('mathexport').onclick=()=>download('recall-mental-math.json',JSON.stringify(h,null,2),'application/json');}
function startMath(retry=null){mathSession={running:true,results:[],question:null,start:Date.now(),deadline:retry||!mathConfig.minutes?0:Date.now()+mathConfig.minutes*60000,limit:retry?retry.length:mathConfig.count,queue:retry?[...retry]:null,answered:false};nextMath();clearInterval(mathTimer);mathTimer=setInterval(()=>{if(!mathSession?.running||page!=='math'){clearInterval(mathTimer);return}let s=mathSession,remaining=s.deadline?Math.max(0,Math.ceil((s.deadline-Date.now())/1000)):Math.floor((Date.now()-s.start)/1000);if($('mathclock'))$('mathclock').textContent=`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`;if(s.deadline&&Date.now()>=s.deadline)endMath()},250)}
function nextMath(){let s=mathSession;if(!s?.running)return;if((s.limit&&s.results.length>=s.limit)||(s.deadline&&Date.now()>=s.deadline)){endMath();return}s.question=s.queue?s.queue.shift():mathQuestion(shuffle(mathConfig.topics)[0],mathConfig.level);s.answered=false;s.questionStart=Date.now();mathDraw()}
function mathDraw(){let s=mathSession,q=s.question;app.innerHTML=`<div class="row spread"><button id="mathend">End session</button><strong id="mathclock">0:00</strong><small>${s.results.length}${s.limit?' / '+s.limit:''} answered</small></div><div class="progress"><i style="width:${s.limit?s.results.length/s.limit*100:0}%"></i></div><div class="panel math-question"><small>${mathTopics[q.topic]}</small><h1>${esc(q.prompt)}</h1><form id="mathform"><label for="mathanswer">Your answer</label><input id="mathanswer" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Type your answer" required><div class="row"><button class="primary" type="submit">Check answer</button><button type="button" id="mathskip">Skip</button></div></form><div id="mathfeedback" aria-live="polite"></div><button id="mathnext" class="primary" hidden>Next question →</button></div><p class="muted">${s.results.filter(r=>r.correct).length} correct · ${s.results.filter(r=>!r.correct).length} missed</p>`;$('mathend').onclick=()=>endMath();$('mathform').onsubmit=e=>{e.preventDefault();submitMath($('mathanswer').value)};$('mathskip').onclick=()=>submitMath('');$('mathnext').onclick=nextMath;$('mathanswer').focus()}
function submitMath(input){let s=mathSession;if(!s?.running||s.answered)return;if(s.deadline&&Date.now()>=s.deadline){endMath();return}s.answered=true;let q=s.question,r={topic:q.topic,prompt:q.prompt,answer:q.answer,tip:q.tip,input,correct:mathCorrect(input,q.answer),seconds:Math.max(.1,(Date.now()-s.questionStart)/1000),time:Date.now()};s.results.push(r);if(!Array.isArray(db.mathHistory))db.mathHistory=[];db.mathHistory.push(r);save();$('mathform').hidden=true;$('mathfeedback').innerHTML=`<h2 class="${r.correct?'math-good':'math-bad'}">${r.correct?'Correct!':'Not quite'}</h2><p>Answer: <strong>${esc(q.answer)}</strong> · ${r.seconds.toFixed(1)} seconds</p><p>${esc(q.tip)}</p>`;$('mathnext').hidden=false;$('mathnext').focus()}
function endMath(show=true){clearInterval(mathTimer);mathTimer=null;let s=mathSession;if(!s)return;s.running=false;if(!show)return;let r=s.results,c=r.filter(x=>x.correct).length;app.innerHTML=`<small>SESSION COMPLETE</small><h1>Mental Math results</h1><div class="grid"><div class="metric"><small>Correct</small><strong>${c}/${r.length}</strong></div><div class="metric"><small>Accuracy</small><strong>${r.length?Math.round(c/r.length*100)+'%':'—'}</strong></div><div class="metric"><small>Average seconds</small><strong>${r.length?(r.reduce((n,x)=>n+x.seconds,0)/r.length).toFixed(1):'—'}</strong></div></div><div class="panel"><h2>Mistakes</h2>${r.filter(x=>!x.correct).map(x=>`<div class="deck"><div><strong>${esc(x.prompt)}</strong><br><small>Your answer: ${esc(x.input||'Skipped')} · Correct: ${esc(x.answer)}</small><p>${esc(x.tip)}</p></div></div>`).join('')||'<p>No missed questions in this session.</p>'}<div class="row"><button class="primary" id="mathhome">New session</button><button id="mathretrycurrent" ${c===r.length?'disabled':''}>Retry these mistakes</button><button id="mathcoach">AI tutor</button></div><div id="mathdetails"></div></div>`;$('mathhome').onclick=()=>{mathSession=null;mathPage()};$('mathretrycurrent').onclick=()=>startMath(r.filter(x=>!x.correct));$('mathcoach').onclick=mathTutor}
function mathTutor(){let h=$('mathcoach')&&mathSession?.results?.length?mathSession.results:mathHistory().slice(-100),wrong=h.filter(r=>!r.correct).slice(-20);let t=`Act as a mental math coach. Teach efficient mental strategies, not calculator methods. My recent results: ${h.length} attempts, ${h.filter(r=>r.correct).length} correct. Mistakes:\n${wrong.map(r=>`${r.prompt} | my answer: ${r.input||'skipped'} | correct: ${r.answer} | ${r.seconds.toFixed(1)} seconds`).join('\n')}\nIdentify weak skills, explain shortcuts step by step, and give 10 fresh targeted questions without showing answers until I attempt them. If there are no mistakes, ask which skills I want to improve.`;$('mathdetails').innerHTML=`<hr><h3>AI tutor · ChatGPT assisted</h3><p>Copy this prompt to ChatGPT for tailored feedback. No data is sent automatically.</p><textarea id="mathprompt" readonly>${esc(t)}</textarea><div class="row"><button id="mathcopy">Copy tutoring prompt</button><a href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT ↗</a></div>`;$('mathcopy').onclick=async()=>{try{await navigator.clipboard.writeText(t);notify('Prompt copied.')}catch{$('mathprompt').select();notify('Select and copy the prompt.')}}}
